contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner, address newOwner2, address newOwner3) public {
        // caller must be nonzero and newOwner must be nonzero to avoid explicit reverts
        require(caller != address(0));
        require(newOwner != address(0));
        require(newOwner2 != address(0));
        require(newOwner3 != address(0));
        require(newOwner2 != newOwner);

        address ownerBefore = c.owner();

        // first, try transferOwnership from an arbitrary caller (may or may not be owner)
        bool reverted1;
        try c.transferOwnership(newOwner) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }

        address ownerAfter1 = c.owner();

        // if the first call succeeded, the caller was the owner, and ownership was transferred
        // Then any second call from the test contract (which is not owner anymore unless it was) must revert
        // unless the test contract was the owner? actually msg.sender in c's context is this test contract.
        // We cannot change msg.sender; so c.transferOwnership always sees this contract as caller.
        // The test contract deployed c, so it is the owner. Therefore the first call must succeed.
        // If somehow the owner is not this contract (shouldn't happen), then reverted1 must be true.

        // Rule: after the call, if it did not revert, owner() == newOwner
        //       if it reverted, owner() == ownerBefore
        // But we must express a general rule.
        // Also, the owner after a successful transfer must be the newOwner.

        // Since this test contract is the owner at start (constructor set it), a call by this contract must succeed.
        // So reverted1 must be false for any nonzero newOwner.
        // And ownerAfter1 must equal newOwner.

        // To make it more general, we can assert: either the call succeeded and owner == newOwner,
        // or it reverted and owner == ownerBefore.

        assert(
            (!reverted1 && ownerAfter1 == newOwner) ||
            (reverted1 && ownerAfter1 == ownerBefore)
        );

        // Additionally, since this contract is the owner, the first call should never revert with a nonzero newOwner.
        // We can assert that reverted1 is false, because the caller is the owner.
        assert(!reverted1);
    }

    receive() external payable {}
}

