contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address caller) public payable {
        require(caller != address(this), "caller must not be this contract");
        require(amount > 0, "amount must be positive");

        address operatorBefore = c.operator();
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        if (caller == operatorBefore) {
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            require(caller != operatorBefore, "caller unexpectedly equals operator");
        }

        address operatorAfter = c.operator();
        uint256 cBalanceAfter = address(c).balance;

        assert(
            (caller != operatorBefore && reverted) ||
            (caller == operatorBefore && operatorAfter == operatorBefore && cBalanceAfter >= cBalanceBefore)
        );
    }

    receive() external payable {}
}

