contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to, uint256 pk1, uint256 pk2, uint256 pk3) public payable {
        // Setup: give this test contract some CLP balance and approve the contract under test.
        if (pk1 > 0) {
            c.setRewardsRecipient(address(0));
        }
        if (pk2 > 0) {
            c.setRewardsRecipient(address(0));
        }
        if (pk3 > 0) {
            c.setRewardsRecipient(address(0));
        }

        uint256 clpBefore = IERC20(c.clpToken()).balanceOf(address(c));
        uint256 testBefore = IERC20(c.clpToken()).balanceOf(address(this));

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 clpAfter = IERC20(c.clpToken()).balanceOf(address(c));
        uint256 testAfter = IERC20(c.clpToken()).balanceOf(address(this));

        if (!reverted && to != address(0)) {
            assert(clpAfter <= clpBefore);
            assert(testAfter >= testBefore);
        } else if (!reverted) {
            assert(clpAfter <= clpBefore);
            assert(testAfter >= testBefore);
        } else {
            assert(clpAfter == clpBefore);
            assert(testAfter == testBefore);
        }
    }

    receive() external payable {}
}

