contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint256 firstEarned;
        bool reverted;

        // The deciding call: must complete for every fresh deployment of P (the CvxPoolInfo
        // reward address is set during deployment), and must behave deterministically.
        try c.earned() returns (uint256 v) {
            firstEarned = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        require(!reverted, "earned() unexpectedly reverted");

        // General rule: the value returned by the completed earned() call equals a
        // second independent read of the same public view on the same contract.
        uint256 secondEarned = c.earned();
        assert(firstEarned == secondEarned);
    }

    receive() external payable {}
}

