                coveredCallReverted = false;
            } catch {
                coveredCallReverted = true;
            }
        }

        assert(
            unauthorizedReverted &&
            (amount > contractClpNow || !coveredCallReverted) &&
            IERC20(c.clpToken()).balanceOf(address(c)) >= contractClpPrev - contractClpNow
        );
    }

    receive() external payable {}
}

