contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address caller) public payable {
        require(true);

        address operator = c.operator();
        bool isShutdown = c.isCvxShutdown();

        bool reverted;
        if (caller == operator) {
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert((caller == operator) == !reverted || (caller == operator && isShutdown && amount > 0));
    }

    receive() external payable {}
}

