            nonOpReverted = false;
        } catch {
            nonOpReverted = true;
        }

        // Non-operator callers must always revert.
        assert(nonOpReverted);

        // Now make the caller the operator and re-run the deciding call.
        c.setOperator(address(this));

        bool opReverted;
        try c.depositAndStake(amount) {
            opReverted = false;
        } catch {
            opReverted = true;
        }

        bool shutdown = c.isCvxShutdown();
        // Operator call reverts exactly when the CVX pool is shutdown.
        assert(opReverted == shutdown);
    }

    receive() external payable {}
}

