contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address caller) public payable {
        IERC20 clp = c.clpToken();

        uint256 balanceBefore = clp.balanceOf(address(c));

        // We cannot set msg.sender directly, so we can only exercise the
        // "operator succeeds / non-operator reverts" distinction when we are
        // the operator. The public observable rule is:
        //   - if msg.sender == operator and c is not shutdown -> deposit succeeds
        //   - if msg.sender != operator -> deposit reverts with NotOperator
        address op = c.operator();
        bool isOperator = (msg.sender == op);

        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = clp.balanceOf(address(c));

        if (!isOperator) {
            // Non-operators must always be rejected, regardless of amount or shutdown.
            assert(reverted && balanceAfter == balanceBefore);
        } else {
            // As the operator we either succeed or revert when the pool is shut down.
            // If we succeed, the contract's clp balance must drop by exactly `amount`
            // (the increaseAllowance plus booster.deposit consumes that many tokens).
            // If the booster itself reverts, the state must remain unchanged.
            assert(
                (!reverted && balanceBefore >= amount && balanceAfter == balanceBefore - amount) ||
                (reverted && balanceAfter == balanceBefore)
            );
        }
    }

    receive() external payable {}
}

