contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newRecipient, bool callerIsOwner) public {
        address prevRecipient = c.rewardsRecipient();

        bytes4 setRecipientSelector = bytes4(keccak256("setRewardsRecipient(address)"));
        bool callSucceeded;
        bytes memory returnData;
        if (callerIsOwner) {
            (callSucceeded, returnData) = address(c).call(
                abi.encodeWithSelector(setRecipientSelector, newRecipient)
            );
        } else {
            (callSucceeded, returnData) = address(c).call(
                abi.encodeWithSelector(setRecipientSelector, newRecipient)
            );
            require(msg.sender != c.owner(), "caller is owner; use callerIsOwner=true");
        }

        address finalRecipient = c.rewardsRecipient();

        if (callerIsOwner) {
            assert(callSucceeded && finalRecipient == newRecipient);
        } else {
            assert(!callSucceeded || finalRecipient == newRecipient);
            assert(!callSucceeded ? finalRecipient == prevRecipient : finalRecipient == newRecipient);
        }
    }
}

