contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address caller) public payable {
        require(caller != address(0));

        // Set caller as operator (onlyOwner call, test contract is owner)
        c.setOperator(caller);

        bool reverted;
        // If the call originates from the test contract (msg.sender), it will be treated as caller
        // In the checker, msg.sender is the test contract, which is the owner, so setOperator succeeds.
        // To make depositAndStake be called by 'caller', we cannot impersonate; however, the rule is about
        // access control: depositAndStake reverts if msg.sender != operator.
        // Since msg.sender is the test contract (owner), if caller == address(this), it does not revert.
        // Otherwise, it reverts with NotOperator.
        // But the test contract is the owner and also the original operator? Actually operator was set in constructor.
        // The rule: depositAndStake reverts iff caller != operator.
        // However, msg.sender is this contract, so depositAndStake will compare msg.sender (this) to operator.
        // To test with caller, we cannot change msg.sender. So we must set operator to this contract to avoid revert,
        // or to something else to force revert.
        // But our focus is on depositAndStake reverting based on access control.
        // We'll set operator to caller, then call depositAndStake. If caller == address(this), it will not revert;
        // otherwise, it will revert because msg.sender (this) != operator (caller).
        // So the rule: reverted == (caller != address(this)).
        // However, we must also consider isCvxShutdown() and booster interactions, but those are external calls
        // that may fail. To avoid that, we need to ensure isCvxShutdown returns false and booster.deposit succeeds.
        // But we cannot control booster. The test environment may have a booster that reverts or returns true.
        // The accepted rule was about access control alone, but the call may also revert due to other reasons.
        // We'll assume the test environment provides a working booster and rewards contract.
        // To be safe, we can only assert the access control part: if caller != address(this), it must revert with NotOperator.
        // But we cannot catch the error type. So we'll assert reverted == (caller != address(this)).
        // This is a general rule: depositAndStake reverts iff caller is not the current operator (which is this contract).
        // Since we set operator = caller, then only when caller == address(this) it does not revert.
        // Actually, if caller = address(this), operator = address(this), so msg.sender == operator, no revert.
        // If caller != address(this), operator = caller, msg.sender = this != operator, so revert.
        // So reverted == (caller != address(this)).
        // But wait: what if amount is huge and booster.deposit reverts? Then it would revert anyway.
        // To avoid that, we can require that amount is 0? But 0 amount might still call booster.deposit.
        // The accepted rule ignored other reverts, but our test might be brittle.
        // We'll keep the rule but note that the test contract is the owner and the operator initially.
        // We'll set operator to caller, then call depositAndStake. The expected revert is true if caller != address(this).
        // If caller == address(this), it should not revert (assuming booster works).

        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == (caller != address(this)));
    }

    receive() external payable {}
}

