contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to) public {
        uint256 balanceBefore = c.clpToken().balanceOf(address(this));

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.clpToken().balanceOf(address(this));

        if (reverted) {
            assert(balanceAfter == balanceBefore);
        } else if (to == address(0)) {
            assert(balanceAfter <= balanceBefore);
        } else {
            assert(balanceAfter >= balanceBefore || balanceBefore - balanceAfter <= amount);
        }
    }
}

