contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, bool claim, address to) public payable {
        uint256 beforeBalance = c.clpToken().balanceOf(to);
        uint256 balanceBefore = c.clpToken().balanceOf(address(c));
        uint256 stakedBefore = c.stakedBalance();

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.clpToken().balanceOf(to);
        uint256 balanceAfter = c.clpToken().balanceOf(address(c));
        uint256 stakedAfter = c.stakedBalance();

        // If the call succeeds and to is nonzero, then:
        //  (1) exactly amount tokens were transferred to `to`
        //  (2) the contract's clp balance plus staked balance decreased by exactly amount (or stayed,
        //      except the amount was fully covered by its own clp balance plus unstaked rewards, so the delta
        //      in `address(c)` balance equals amount only when withdrawn from rewards)
        if (!reverted && to != address(0)) {
            // The contract must transfer exactly `amount` to `to` when to is nonzero.
            assert(afterBalance >= beforeBalance && afterBalance - beforeBalance == amount);
            // If the contract didn't already hold enough clpToken, it must have unstaked the difference
            // from the reward pool; otherwise its own balance must have been reduced by `amount`.
            if (balanceBefore >= amount) {
                assert(balanceAfter + amount == balanceBefore && stakedAfter == stakedBefore);
            } else {
                // toUnstake = amount - balanceBefore was withdrawn and unwrapped, so staked decreased
                // by at least that amount, and balanceAfter should be zero (exactly amount transferred
                // to `to` after unwrap).
                assert(balanceAfter == 0);
                assert(stakedBefore >= stakedAfter);
            }
        }
        // If to is zero, no transfer should happen: `to`'s balance must be unchanged.
        if (!reverted && to == address(0)) {
            assert(afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

