contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public {
        // configuration visible through c's public surface
        (address token, address rewards, uint32 pId) = c.cvxPoolInfo();

        // snapshot other observable state before the call
        uint256 balBefore = c.clpToken().balanceOf(address(c));
        address opBefore = c.operator();
        address rrBefore = c.rewardsRecipient();
        address clpBefore = address(c.clpToken());
        address boosterBefore = address(c.booster());

        bool shutdown = c.isCvxShutdown();

        // idempotence: a second read returns the same value
        bool shutdownAgain = c.isCvxShutdown();

        // state unchanged by read-only call
        uint256 balAfter = c.clpToken().balanceOf(address(c));
        address opAfter = c.operator();
        address rrAfter = c.rewardsRecipient();

        assert(
            shutdown == shutdownAgain &&
            opAfter == opBefore &&
            rrAfter == rrBefore &&
            clpAfter == clpBefore &&
            boosterAfter == boosterBefore &&
            balAfter == balBefore
        );
    }

    receive() external payable {}
}

